 "<html>
<head>
<meta http-equiv="Content-type" content="text/html;charset=UTF-8">
<style>
html, body { background-color: white; }
table { border-collapse:collapse; border:none; }
caption { font-weight: bold; text-align:left; }
td {  }
.thead { border-top: double; text-align:center; font-style:normal; font-weight:bold; padding:0.2cm; }
.tdata { padding:0.2cm; text-align:left; vertical-align:top; }
.arc { background-color:#f2f2f2; }
.summary { padding-top:0.1cm; padding-bottom:0.1cm; }
.summarydata { text-align:left; }
.fixedparts { font-weight:bold; text-align:left; }
.randomparts { font-weight:bold; text-align:left; padding-top:.8em; }
.zeroparts { font-weight:bold; text-align:left; padding-top:.8em; }
.simplexparts { font-weight:bold; text-align:left; padding-top:.8em; }
.lasttablerow { border-bottom: double; }
.firsttablerow {  }
.firstsumrow { border-top:1px solid; }
.labelcellborder { border-bottom:1px solid; }
.depvarhead { text-align:center; border-bottom:1px solid; font-style:italic; font-weight:normal; }
.depvarheadnodv { border-top: double; text-align:center; border-bottom:1px solid; font-style:italic; font-weight:normal; }
.leftalign { text-align:left; }
.centeralign { text-align:center; }
.firsttablecol { text-align:left; }
.footnote { font-style:italic; border-top:double black; text-align:right; }
.subtitle { font-weight: normal; }
.modelcolumn1 {  }
.modelcolumn2 {  }
.modelcolumn3 {  }
.modelcolumn4 {  }
.modelcolumn5 {  }
.modelcolumn6 {  }
.modelcolumn7 {  }
.col1 {  }
.col2 {  }
.col3 {  }
.col4 {  }
.col5 {  }
.col6 {  }
</style>
</head>
<body>
<table>
  <tr>
    <th class="thead firsttablerow firsttablecol col1">&nbsp;</th>
    <th colspan="3" class="thead firsttablerow">Eficiencia y Conservación<br>de Recursos en el hogar</th>
  </tr>
  <tr>
    <td class="depvarhead firsttablerow firsttablecol col1">Predictors</td>
    <td class="depvarhead firsttablerow col2">Estimates</td>
    <td class="depvarhead firsttablerow col3">std(b)</td>
    <td class="depvarhead firsttablerow col4">p</td>
  </tr>
  <tr>
    <td class="tdata firsttablecol col1">(Intercept)</td>
    <td class="tdata centeralign modelcolumn1 col2">&#45;0.12</td>
    <td class="tdata centeralign modelcolumn1 col3">&#45;0.08</td>
    <td class="tdata centeralign modelcolumn1 col4">0.179</td>
</tr>
  <tr>
    <td class="tdata firsttablecol col1">Tramo de Edad del<br>encuestado</td>
    <td class="tdata centeralign modelcolumn1 col2">0.01</td>
    <td class="tdata centeralign modelcolumn1 col3">0.19</td>
    <td class="tdata centeralign modelcolumn1 col4"><strong>&lt;0.001</strong></td>
</tr>
  <tr>
    <td class="tdata firsttablecol col1">: SEXO2</td>
    <td class="tdata centeralign modelcolumn1 col2">0.08</td>
    <td class="tdata centeralign modelcolumn1 col3">0.15</td>
    <td class="tdata centeralign modelcolumn1 col4"><strong>0.002</strong></td>
</tr>
  <tr>
    <td class="tdata firsttablecol col1">Falta de tiempo para<br>reciclar</td>
    <td class="tdata centeralign modelcolumn1 col2">&#45;0.07</td>
    <td class="tdata centeralign modelcolumn1 col3">&#45;0.13</td>
    <td class="tdata centeralign modelcolumn1 col4"><strong>&lt;0.001</strong></td>
</tr>
  <tr>
    <td class="tdata firsttablecol col1">Preferencia: Comprar<br>nuevo vs. Reparar</td>
    <td class="tdata centeralign modelcolumn1 col2">&#45;0.07</td>
    <td class="tdata centeralign modelcolumn1 col3">&#45;0.15</td>
    <td class="tdata centeralign modelcolumn1 col4"><strong>&lt;0.001</strong></td>
</tr>
  <tr>
    <td class="tdata firsttablecol col1">Escepticismo: Utilidad<br>real del reciclaje</td>
    <td class="tdata centeralign modelcolumn1 col2">&#45;0.04</td>
    <td class="tdata centeralign modelcolumn1 col3">&#45;0.09</td>
    <td class="tdata centeralign modelcolumn1 col4"><strong>&lt;0.001</strong></td>
</tr>
  <tr>
    <td class="tdata firsttablecol col1">Responsabilidad: Deber de<br>reciclar</td>
    <td class="tdata centeralign modelcolumn1 col2">0.08</td>
    <td class="tdata centeralign modelcolumn1 col3">0.14</td>
    <td class="tdata centeralign modelcolumn1 col4"><strong>&lt;0.001</strong></td>
</tr>
  <tr>
    <td class="tdata leftalign summary firstsumrow">Observations</td>
    <td class="tdata summary summarydata firstsumrow" colspan="3">1623</td>
  </tr>
  <tr>
    <td class="tdata leftalign summary">R<sup>2</sup> / R<sup>2</sup> adjusted</td>
    <td class="tdata summary summarydata" colspan="3">0.148 / 0.145</td>
  </tr>

</table>

</body></html>"
